    template <class Self>
    inline void IconGlyphBase<Self>::update() {
      using namespace IconGlyph_detail;
      mark_all_dirty();
      flush_update();
    }
    template <class Self>
    inline void IconGlyphBase<Self>::flush_update() {
      using namespace IconGlyph_detail;
      update_effects();
      apply_state();
    }
    template <class Self>
    inline void IconGlyphBase<Self>::note_dirty(std::size_t bit) {
      using namespace IconGlyph_detail;
      dirty_.set(bit);
    }
    template <class Self>
    inline void IconGlyphBase<Self>::mark_all_dirty() {
      using namespace IconGlyph_detail;
      dirty_.set_all();
    }
    template <class Self>
    inline void IconGlyphBase<Self>::attach_scheduler(tessera::ui::UpdateScheduler& scheduler) {
      using namespace IconGlyph_detail;
      update_ticket_.context = this;
      update_ticket_.update = [](void* context) {
        static_cast<IconGlyphBase<Self>*>(context)->flush_update();
      };
      scheduler.attach(update_ticket_);
    }
    template <class Self>
    inline void IconGlyphBase<Self>::detach_scheduler(tessera::ui::UpdateScheduler& scheduler) {
      using namespace IconGlyph_detail;
      scheduler.detach(update_ticket_);
    }
    template <class Self>
    inline void IconGlyphBase<Self>::schedule_update() {
      using namespace IconGlyph_detail;
      update_ticket_.schedule();
    }
